@lru_cache(maxsize=None)
def _decode(payload: str) -> str:
    return zlib.decompress(base64.b85decode(payload.encode("ascii"))).decode("utf-8")


def get_other_base_text() -> str:
    return _decode(_OTHER_B85)


def get_ipset_all_base_text() -> str:
    return _decode(_IPSET_ALL_B85)


def get_ipset_ru_base_text() -> str:
    return _decode(_IPSET_RU_B85)
